def inside_notes(path: str) -> bool:
    """True when path, taken relative to notes, stays at or below notes."""
    ex inside_notes("a.txt") == True
    ex inside_notes("sub/b.txt") == True
    ex inside_notes("../secret.txt") == False
    ex inside_notes("sub/../../secret.txt") == False
    depth = 0
    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            depth -= 1
            if depth < 0:
                return False
        else:
            depth += 1
    return True

def plugin(path: str) -> str uses fs:
    """Read path and notes/../secret.txt through fs; a read that fails gives an empty part."""
    post "|" in out
    mine = fs.read(path) else ""
    theirs = fs.read("notes/../secret.txt") else ""
    return mine + "|" + theirs

def run_plugin(path: str) -> str uses fs:
    """Return plugin(path) run with fs narrowed to notes, so reads outside notes give ''."""
    pre path != ""
    post "|" in out
    with fs = fs.sub("notes"):
        return plugin(path)
